--
-- Table structure for table `attendance`
--

DROP TABLE IF EXISTS `attendance`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `attendance` (
  `attendance_id` bigint NOT NULL AUTO_INCREMENT,
  `student_id` varchar(20) NOT NULL,
  `course_id` varchar(20) NOT NULL,
  `classes_conducted` int NOT NULL,
  `classes_attended` int NOT NULL,
  `attendance_percentage` decimal(5,2) DEFAULT NULL,
  PRIMARY KEY (`attendance_id`),
  UNIQUE KEY `uq_attendance_student_course` (`student_id`,`course_id`),
  KEY `fk_attendance_course` (`course_id`),
  CONSTRAINT `fk_attendance_course` FOREIGN KEY (`course_id`) REFERENCES `course` (`course_id`),
  CONSTRAINT `fk_attendance_student` FOREIGN KEY (`student_id`) REFERENCES `student` (`student_id`),
  CONSTRAINT `chk_attendance_valid` CHECK ((`classes_attended` <= `classes_conducted`)),
  CONSTRAINT `chk_classes_attended` CHECK ((`classes_attended` >= 0)),
  CONSTRAINT `chk_classes_conducted` CHECK ((`classes_conducted` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=181 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

